class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(limit):
            if limit == 1:
                mismatch = sum(1 for i, ch in enumerate(s) if int(ch) != i % 2)
                return min(mismatch, n - mismatch) <= numOps
            ops = 0
            run = 1
            for i in range(1, n + 1):
                if i < n and s[i] == s[i - 1]:
                    run += 1
                else:
                    ops += run // (limit + 1)
                    run = 1
            return ops <= numOps

        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            if feasible(mid):
                high = mid
            else:
                low = mid + 1
        return low

