                    run += 1
                else:
                    ops += run // (limit + 1)
                    run = 1
            return ops <= numOps

        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            if feasible(mid):
                high = mid
            else:
                low = mid + 1
        return low
